// Xbox reads mip 3 of the UI backdrop; on PC that target has one mip, so blur mip 0 instead (~mip 3 footprint).
float4 blur_mip3_(Texture2D tx, SamplerState sm, float2 uv) {
  uint w, h; tx.GetDimensions(w, h); float2 px = 4.0 / float2(w, h); float4 acc = 0; float ws = 0;
  [unroll] for (int y = -3; y <= 3; ++y) [unroll] for (int x = -3; x <= 3; ++x) {
    float g = exp(-(float)(x * x + y * y) / 6.0); acc += tx.SampleLevel(sm, uv + float2(x, y) * px, 0) * g; ws += g; }
  return acc / ws;
}
float4 blur_g_(bool e, Texture2D tx, SamplerState sm, float2 uv) { float4 r = 0; [branch] if (e) r = blur_mip3_(tx, sm, uv); return r; }
